{"compatibility":"minor","safety_note_md":"# SafeStan Safety Note

Compatibility: minor.

Protected data: `Y`.

Generated files: `model_safe.stan`, `data_safe.json`.

Changes: reordered parameter prior sampling statements so every parameter is given its prior before any model-block use. Replaced the looped prior `alpha[m] ~ multi_normal(gamma, Sigma)` with the equivalent vectorized top-level statement `alpha ~ multi_normal(gamma, Sigma)`, which preserves the same summed log density while satisfying SafeStan's requirement that parameter priors are not placed inside loops and use top-level parameter identifiers. No data changes were made.
","model_safe_stan":"// Schools: ranking school examination resutls using
// multivariate hierarcical models
//  http://www.openbugs.net/Examples/Schools.html

data {
  int<lower=0> N;
  int<lower=0> M;
  vector[N] LRT;
  array[N] int school;
  array[N, 3] int School_denom;
  array[N, 2] int School_gender;
  array[N, 2] int VR;
  array[N] real Y;
  array[N] int Gender;
  cov_matrix[3] R;
}
transformed data {
  vector[3] gamma_mu;
  cov_matrix[3] gamma_Sigma;
  cov_matrix[3] invR;
  invR = inverse(R);
  gamma_mu[1] = 0;
  gamma_mu[2] = 0;
  gamma_mu[3] = 0;
  for (i in 1 : 3) {
    for (j in 1 : 3) {
      gamma_Sigma[i, j] = 0;
    }
  }
  for (i in 1 : 3) {
    gamma_Sigma[i, i] = 100;
  }
}
parameters {
  array[8] real beta;
  array[M] vector[3] alpha;
  vector[3] gamma;
  cov_matrix[3] Sigma;
  real theta;
  real phi;
}
model {
  array[N] real Ymu;

  // Priors for fixed effects:
  beta ~ normal(0, 100);
  theta ~ normal(0.0, 100);
  phi ~ normal(0.0, 100);

  // Hyper-priors:
  gamma ~ multi_normal(gamma_mu, gamma_Sigma);
  Sigma ~ inv_wishart(3, invR);

  // Priors for random coefficients:
  alpha ~ multi_normal(gamma, Sigma);

  for (p in 1 : N) {
    Ymu[p] = alpha[school[p], 1] + alpha[school[p], 2] * LRT[p]
             + alpha[school[p], 3] * VR[p, 1] + beta[1] * LRT[p] * LRT[p]
             + beta[2] * VR[p, 2] + beta[3] * Gender[p]
             + beta[4] * School_gender[p, 1] + beta[5] * School_gender[p, 2]
             + beta[6] * School_denom[p, 1] + beta[7] * School_denom[p, 2]
             + beta[8] * School_denom[p, 3];
  }
  Y ~ normal(Ymu, exp(-.5 * (theta + phi * LRT)));
  //  for(p in 1:N) {
  //     Y[p] ~ normal(,  exp(-.5 * (theta + phi * LRT[p])));
  //  }
  // min.var <- exp(-(theta + phi * (-34.6193))) // lowest LRT score = -34.6193
  // max.var <- exp(-(theta + phi * (37.3807)))  // highest LRT score = 37.3807
}
generated quantities {
  // real alpha1[M];
  array[M] real ranks;
  // for (m in 1:M)  alpha1[m] <- alpha[m, 1];
  //# compute ranks
  for (j in 1 : M) {
    array[M] real greater_than;
    for (k in 1 : M) {
      greater_than[k] = step(alpha[k, 1] - alpha[j, 1]);
    }
    ranks[j] = sum(greater_than);
  }
}
